// Generates src/generated/*.ts from every schemas/*.schema.json with
// json-schema-to-typescript. `--check` fails (exit 1) when a generated file
// is missing, stale, or orphaned instead of writing.
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const schemasDir = join(root, "schemas");
const outDir = join(root, "src", "generated");
const check = process.argv.includes("--check");

const banner =
  "// Generated by packages/contracts/scripts/generate.ts from schemas/{file}. Do not edit.\n// Run `pnpm contracts:generate` after changing the schema.";

const schemaFiles = readdirSync(schemasDir)
  .filter((f) => f.endsWith(".schema.json"))
  .sort();

// `anyOf`/`oneOf` whose branches only list `required` keys (e.g. "complaintText or
// audio") are runtime-only constraints: Ajv enforces them, but json-schema-to-typescript
// would turn them into an open index signature. Strip them before generating types.
function stripRequiredOnlyCombinators(node: unknown): unknown {
  if (Array.isArray(node)) return node.map(stripRequiredOnlyCombinators);
  if (node === null || typeof node !== "object") return node;
  const out: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(node)) {
    const requiredOnly =
      (key === "anyOf" || key === "oneOf") &&
      Array.isArray(value) &&
      value.every(
        (branch) => branch !== null && typeof branch === "object" && Object.keys(branch).every((k) => k === "required"),
      );
    if (!requiredOnly) out[key] = stripRequiredOnlyCombinators(value);
  }
  return out;
}

const readSchema = (file: string): unknown => JSON.parse(readFileSync(join(schemasDir, file), "utf8"));

/**
 * The named types a schema takes from other schema files through `$ref`
 * (`other.schema.json#/json/pointer` to a node with a `title`), each imported from the
 * file generated for it so the type is declared once. A reference to an untitled node
 * (a plain string, say) is simply inlined.
 */
function externalTypes(node: unknown, found = new Map<string, string>()): Map<string, string> {
  if (Array.isArray(node)) for (const item of node) externalTypes(item, found);
  if (node === null || typeof node !== "object") return found;
  for (const [key, value] of Object.entries(node)) {
    const ref = key === "$ref" && typeof value === "string" ? /^([\w-]+)\.schema\.json#(.*)$/.exec(value) : null;
    if (!ref) {
      externalTypes(value, found);
      continue;
    }
    const [, target = "", pointer = ""] = ref;
    let resolved = readSchema(`${target}.schema.json`) as Record<string, unknown> | undefined;
    for (const part of pointer.split("/").filter(Boolean)) resolved = resolved?.[part] as typeof resolved;
    if (typeof resolved?.title === "string") found.set(resolved.title, target);
  }
  return found;
}

const expected = new Map<string, string>();
for (const file of schemaFiles) {
  const schema = stripRequiredOnlyCombinators(readSchema(file)) as { title?: string };
  const imported = externalTypes(schema);
  const ts = await compile(schema, schema.title ?? file, {
    bannerComment: [
      banner.replace("{file}", file),
      ...(imported.size > 0 ? [""] : []),
      ...[...imported].map(([title, target]) => `import type { ${title} } from "./${target}.js";`),
    ].join("\n"),
    cwd: schemasDir,
    additionalProperties: false,
    unreachableDefinitions: true,
    strictIndexSignatures: true,
    ignoreMinAndMaxItems: true,
    // A type from another file is imported (above), not declared again. This also
    // leaves out every named type but the root, so such a schema keeps its own named
    // parts in a file of their own.
    declareExternallyReferenced: imported.size === 0,
    format: true,
    style: { semi: true, singleQuote: false, trailingComma: "all", printWidth: 100 },
  });
  expected.set(file.replace(/\.schema\.json$/, ".ts"), ts);
}

const index = [
  banner.replace("{file}", "*.schema.json"),
  "",
  ...[...expected.keys()].map((f) => `export type * from "./${f.replace(/\.ts$/, ".js")}";`),
  "",
].join("\n");
expected.set("index.ts", index);

if (check) {
  const problems: string[] = [];
  for (const [name, content] of expected) {
    const path = join(outDir, name);
    if (!existsSync(path)) problems.push(`missing: src/generated/${name}`);
    else if (readFileSync(path, "utf8") !== content) problems.push(`stale: src/generated/${name}`);
  }
  if (existsSync(outDir)) {
    for (const name of readdirSync(outDir)) {
      if (!expected.has(name)) problems.push(`orphaned: src/generated/${name}`);
    }
  }
  if (problems.length > 0) {
    console.error(`Generated contracts are out of date. Run \`pnpm contracts:generate\`.\n${problems.join("\n")}`);
    process.exit(1);
  }
  console.log(`Generated contracts are current (${expected.size} files).`);
} else {
  mkdirSync(outDir, { recursive: true });
  for (const name of readdirSync(outDir)) {
    if (!expected.has(name)) rmSync(join(outDir, name));
  }
  for (const [name, content] of expected) writeFileSync(join(outDir, name), content);
  console.log(`Wrote ${expected.size} files to src/generated/.`);
}
